41	fn parse_port_prefix(input: &str) -> i32 {
42	    let digits = input
43	        .as_bytes()
44	        .iter()
45	        .take_while(|byte| byte.is_ascii_digit())
46	        .count();
47	
48	    if digits == 0 {
49	        return -1;
50	    }
51	
52	    match input[..digits].parse::<u32>() {
53	        Ok(port) if port <= 65_535 => port as i32,
54	        _ => -1,
55	    }
56	}

